import {NFL_TEAMS} from '../../season-stats.js';
export function standingsFixture(year=2026){
 const divisions={AFC:{East:[['2',5],['15',9],['17',1],['20',13]],North:[['33',6],['4',10],['5',14],['23',2]],South:[['34',7],['11',11],['30',3],['10',15]],West:[['7',4],['12',8],['13',16],['24',12]]},NFC:{East:[['6',9],['19',13],['21',1],['28',5]],North:[['3',2],['8',10],['9',7],['16',14]],South:[['1',11],['29',3],['18',15],['27',8]],West:[['22',16],['14',12],['25',6],['26',4]]}};
 const stat=(name,value,displayValue=String(value),extra={})=>({name,value,displayValue,...extra});
 return {season:{year},children:Object.entries(divisions).map(([conference,groups])=>({abbreviation:conference,children:Object.entries(groups).map(([division,entries])=>({name:conference+' '+division,standings:{entries:entries.map(([id,seed])=>{const name=NFL_TEAMS.find(t=>t[0]===id)[1],clinch=seed===1?['*','Clinched Homefield Advantage']:seed<=4?['z','Clinched Division']:seed<=7?['y','Clinched Playoff Berth']:seed===16?['e','Eliminated From Playoffs']:null;return {team:{id,displayName:name,shortDisplayName:name.split(' ').at(-1),abbreviation:id==='25'?'SF':name.slice(0,3).toUpperCase()},stats:[stat('playoffSeed',seed),stat('wins',8),stat('losses',8),stat('ties',1),stat('winPercent',.5,'.500'),stat('pointsFor',300),stat('pointsAgainst',250),stat('pointDifferential',50,'+50'),stat('divisionRecord',0,'3-3'),stat('Home',0,'4-4-1',{type:'home'}),stat('Road',0,'4-4',{type:'road'}),stat('vs. Conf.',0,'6-6',{type:'vsconf'}),stat('streak',2,'W2'),...(clinch?[stat('clincher',0,clinch[0],{description:clinch[1]})]:[])]};})}}))}))};
}
